tau = 0.7; a2 = 2.0
th_shift = lap(lambda t: np.exp(-(t - tau)), p0, tau).real; assert abs(th_shift - np.exp(-p0*tau)*F1(p0)) < 1e-9
th_sim = lap(lambda t: np.exp(-a2*t), p0).real; assert abs(th_sim - F1(p0/a2)/a2) < 1e-9
