report("th_shift", th_shift, ".4f"); report("th_sim", th_sim, ".4f"); report("th_mod", th_mod, ".4f"); report("th_der", th_der, ".4f")
report("th_int", th_int, ".4f"); report("th_conv", th_conv, ".4f"); report("th_ac", th_ac, ".4f")
