assert abs(ftn - 1/(1 + pF)) < 1e-10; report("fl_mag", abs(ftn), ".4f")
ft2 = integrate.quad(lambda t: np.exp(-abs(t))*np.cos(2*np.pi*f0*t), -60, 60, points=[0], limit=400)[0]
